// Marks a tool's own open or import, whose loads it reports itself.
class ToolLoad
{
public:
    explicit ToolLoad(int& count) : m_count(count) { ++m_count; }
    ~ToolLoad() { --m_count; }
    ToolLoad(const ToolLoad&)            = delete;
    ToolLoad& operator=(const ToolLoad&) = delete;

